from enum import Enum
from typing import Annotated, TypeAlias

from ...core import open_enum_validator


class GiftCardGansource(str, Enum):
    """Indicates the source that generated the gift card account number (GAN)."""

    SQUARE = "SQUARE"
    """The GAN is generated by Square."""

    OTHER = "OTHER"
    """The GAN is provided by a non-Square system. For more information, see `Custom GANs
    <https://developer.squareup.com/docs/gift-cards/using-gift-cards-api#custom-gans>`__ or `Third-party gift cards
    <https://developer.squareup.com/docs/gift-cards/using-gift-cards-api#third-party-gift-cards>`__."""

    __str__ = str.__str__


GiftCardGansourceOrStr: TypeAlias = Annotated[GiftCardGansource | str, open_enum_validator(GiftCardGansource)]
